  'sqX5fTAKqUuNRwdoxaag', 'uclYhjBFIyedqd8xqYwE', 'VLoxJWATbFZMgMOfBb4P', 'kjvFHgnOa8iVNV7YiiBN', 'LNdrE1FEgFjbPydSCntV',
  'FohJiIh9tGFKXI02LSUD', 'crnTGUSW3StY8VTOqaR2', 'EI2ls6K7uJFe75PmRPaX', 'U26ojrxlzQxC1kwAMvki', 'O5yyMN7TXsWzblxrHUfO'];
const CONTACT_FIELDS = ['st1eCAFAHDcgPM4VvtNn', 'zntmhqZEVR510izM1Amv', '2qGuyylBHmeIFy4ZQITo', 'O5yyMN7TXsWzblxrHUfO'];
// ===== end of settings =====

// Shared helpers (pasted into each Validate node after the settings).
const clean = o => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== ''));
const str = (v, n = 200) => (v == null ? '' : String(v)).trim().slice(0, n);
const isEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);
function phoneE164(v) {
  const raw = str(v, 40); if (!raw) return '';
  const digits = raw.replace(/\D/g, '');
  if (raw.startsWith('+')) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;            // US/Canada without country code
  if (digits.length === 11 && digits[0] === '1') return '+' + digits;
  return raw;                                                // leave anything else for HighLevel to parse
}
function pickFields(list, allowed) {
  const ok = new Set(allowed);
  return (Array.isArray(list) ? list : []).filter(f => f && ok.has(f.id)).map(f => ({
    id: f.id,
    fieldValue: Array.isArray(f.fieldValue) ? f.fieldValue.map(x => str(x, 200)).slice(0, 25)
      : typeof f.fieldValue === 'number' ? f.fieldValue : str(f.fieldValue, 5000)
  }));
}
function clientIp(headers) {
  const h = headers || {};
  return str(h['cf-connecting-ip'] || h['x-forwarded-for'] || h['x-real-ip'] || '', 100).split(',')[0].trim();
}
function contextLines(ctx) {
  ctx = ctx || {};
  const utm = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid', 'msclkid']
    .filter(k => ctx[k]).map(k => `${k}: ${str(ctx[k], 200)}`);
  return [`Page: ${str(ctx.page_url, 500)}`, `Landing page: ${str(ctx.landing_page, 500)}`,
    `Referrer: ${str(ctx.first_referrer || ctx.referrer, 500) || 'direct'}`, ...utm];
}
const reject = (code, message, status = 400) => [{ json: { ok: false, status, code, message } }];

// Turn the website's month request into a safe HighLevel free-slots query (max 31 days, never in the past).
const q = $input.first().json.query || {};
let start = Number(q.start), end = Number(q.end);
let timezone = str(q.timezone, 60) || 'America/New_York';
try { new Intl.DateTimeFormat('en-US', { timeZone: timezone }); } catch (e) { timezone = 'America/New_York'; }
if (!isFinite(start) || !isFinite(end)) return [{ json: { ok: false } }];
start = Math.max(start, Date.now());
end = Math.min(end, start + 31 * 86400000);
if (end <= start) return [{ json: { ok: false } }];
return [{ json: { ok: true, calendarId: CALENDAR_ID, start: Math.floor(start), end: Math.floor(end), timezone } }];

// Pass on only the date → slots map the website needs.
const prev = $('Validate').first().json;
const r = $input.first().json;
if (!prev.ok) return [{ json: { status: 200, body: {} } }];
if (!(r.statusCode >= 200 && r.statusCode < 300)) return [{ json: { status: 502, body: { error: 'availability_unavailable' } } }];
const out = {};
for (const [day, v] of Object.entries(r.body || {})) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(day) && v && Array.isArray(v.slots)) out[day] = { slots: v.slots.filter(s => typeof s === 'string') };
}
return [{ json: { status: 200, body: out } }];
